import { revalidatePath } from 'next/cache';
import { getNotificationPreference, setNotificationPreference } from '@/lib/notification-store';

export async function toggleNotification() {
  const current = getNotificationPreference();
  setNotificationPreference(!current);
  revalidatePath('/');
}

